"""Minimal SMILES graph reader + Weisfeiler-Lehman signature, for offline measurement."""
import re, hashlib
from collections import Counter, defaultdict

AROM = set("bcnops")
ORGANIC = ["Cl", "Br", "B", "C", "N", "O", "P", "S", "F", "I"]


def parse(smiles):
    """Return (atoms, bonds) for a dot-separated SMILES; components kept separate."""
    components = []
    for comp in smiles.split("."):
        comp = comp.strip()
        if not comp:
            continue
        atoms = []      # (element, aromatic, charge, nH)
        bonds = []      # (i, j, order)
        prev = None
        pending = None  # pending bond order
        stack = []
        rings = {}
        i = 0
        while i < len(comp):
            ch = comp[i]
            if ch == "[":  # bracketed atom
                j = comp.index("]", i)
                body = comp[i + 1:j]
                m = re.match(r"^\d*([A-Za-z][a-z]?)(@{1,2}|@@)?(H\d*)?([+-]\d*|\+\+|--)?", body)
                el = m.group(1)
                hs = m.group(3)
                charge = 0
                if m.group(4):
                    c = m.group(4)
                    if c in ("+", "-"):
                        charge = 1 if c == "+" else -1
                    elif c[0] in "+-":
                        num = c[1:]
                        charge = (1 if c[0] == "+" else -1) * (int(num) if num else 1)
                nH = int(hs[1:]) if hs and len(hs) > 1 else (1 if hs else 0)
                aromatic = el.islower()
                atoms.append((el.capitalize(), aromatic, charge, nH))
                i = j + 1
            elif ch == "(":
                stack.append(prev); i += 1; continue
            elif ch == ")":
                prev = stack.pop(); i += 1; continue
            elif ch in "-=#$:/\\":
                pending = {"-": 1, "=": 2, "#": 3, "$": 1, ":": 1.5, "/": 1, "\\": 1}[ch]
                i += 1; continue
            elif ch.isdigit() or ch == "%":
                if ch == "%":
                    num = comp[i + 1:i + 3]; i += 3
                else:
                    num = ch; i += 1
                if num in rings:
                    other, order = rings.pop(num)
                    order = pending if pending is not None else order
                    if order is None:
                        order = 1.5 if (atoms[prev][1] and atoms[other][1]) else 1
                    bonds.append((other, prev, order))
                else:
                    rings[num] = (prev, pending)
                pending = None
                continue
            else:
                el = None
                for cand in ORGANIC:
                    if comp.startswith(cand, i) and (cand not in ("B", "C", "N", "O", "P", "S", "F", "I") or not comp[i + 1:i + 2].islower()):
                        el = cand; break
                if el is None and ch in AROM:
                    el = ch
                if el is None:
                    raise ValueError(f"cannot read {comp!r} at {i}: {comp[i:i+8]}")
                aromatic = el.islower()
                atoms.append((el.upper(), aromatic, 0, 0))
                i += len(el)
            if prev is not None and i <= len(comp):
                # a bond to the previous atom is added unless this atom opened a ring above
                pass
            if prev is not None and len(bonds) + len(rings) >= 0:
                pass
            # add the bond from prev to the atom just added
            if atoms and prev is not None:
                last = len(atoms) - 1
                order = pending if pending is not None else (1.5 if (atoms[last][1] and atoms[prev][1]) else 1)
                bonds.append((prev, last, order))
            if atoms:
                prev = len(atoms) - 1
            pending = None
        components.append((atoms, bonds))
    return components


def signature(comp):
    """WL-refined isomorphism signature of one component (multiset of final labels)."""
    atoms, bonds = comp
    n = len(atoms)
    adj = defaultdict(list)
    for i, j, o in bonds:
        adj[i].append((j, o)); adj[j].append((i, o))
    labels = []
    for i in range(n):
        el, arom, charge, nH = atoms[i]
        labels.append((el, arom, charge, nH, len(adj[i])))
    for _ in range(n):
        nxt = []
        for i in range(n):
            nb = sorted((o, labels[j]) for j, o in adj[i])
            nxt.append(hashlib.md5(repr((labels[i], tuple(nb))).encode()).hexdigest()[:10])
        if nxt == labels:
            break
        labels = nxt
    return hashlib.md5(repr(sorted(labels)).encode()).hexdigest()


def components(smiles):
    return Counter(signature(c) for c in parse(smiles))


def formula(smiles):
    out = Counter()
    if not smiles:
        return out
    for atoms, _ in parse(smiles):
        for el, arom, charge, nH in atoms:
            out[el] += 1
            out["H"] += nH
    return out


def equivalent(a, b):
    return components(a) == components(b)

