"""Minimal SMILES graph reader + Weisfeiler-Lehman signature, for offline measurement."""
import re, hashlib
from collections import Counter, defaultdict

AROM = set("bcnops")
BOND = {"-": 1, "=": 2, "#": 3, "$": 1, ":": 1.5, "/": 1, "\\": 1}


def _atom(token):
    """(element, aromatic, charge, nH) for one bracketed or plain atom token."""
    if token.startswith("["):
        body = token[1:-1]
        m = re.match(r"^\d*([A-Za-z][a-z]?)(?:@{1,2})?(H\d*)?([+-]\d*|\+\+|--)?", body)
        el = m.group(1)
        hs = m.group(2)
        nH = int(hs[1:]) if hs and len(hs) > 1 else (1 if hs else 0)
        charge = 0
        if m.group(3):
            c = m.group(3)
            if c[0] in "+-":
