"""Offline comparison of ranking variants over the three frozen memories and Val questions."""
import json, sys, math
sys.path.insert(0, '/workspace/harness/solver')
from collections import Counter
from tools.retrieval import _ngrams, _word_ngrams, joiner_separator, NGRAM

RUN = '/workspace/runs/e4b5fa6f8c6543fea051453433e4226e2d1bfc74'


def load(task):
    return json.load(open(f'{RUN}/{task}/memory.json'))['examples']


def sim(left, right):
    if not left or not right:
        return 0.0
    return sum((left & right).values()) / (sum(left.values()) * sum(right.values())) ** 0.5


def carry_counts(docs, reader):
    counts = Counter()
    for text in docs:
        counts.update(set(reader(text)))
    return counts


def make_ranker(examples, reader, variant, cutoff=0.05, mix=None):
    """variant: 'query-log' | 'both-log' | 'cutoff' | 'both-cutoff'"""
    inputs = tuple(e['input'] for e in examples)
    N = len(inputs)
    carried = carry_counts(inputs, reader)

    def weight(gram):
        if variant in ('cutoff', 'both-cutoff'):
            return 1.0 if carried[gram] <= cutoff * N else 0.0
        return math.log((N + 1) / (carried[gram] + 1))

    def rank(question):
        query = Counter()
        for gram, count in reader(question).items():
            w = weight(gram)
            if w > 0:
                query[gram] = count * w
        docs = []
        for e in examples:
            counts = reader(e.get('raw_question', e['input']))
            if variant in ('both-log', 'both-cutoff'):
                counts = Counter({g: c * weight(g) for g, c in counts.items() if weight(g) > 0})
            docs.append(counts)
        scored = [(sim(query, doc), i) for i, doc in enumerate(docs)]
        scored.sort(key=lambda p: (-p[0], p[1]))
        return [examples[i] for _, i in scored]

    return rank


def char_reader(text):
    return _ngrams(text)


def lawbench_metrics(rank):
    ex = load('LawBench')
    j = joiner_separator(ex)
    va = [json.loads(l) for l in open('/workspace/benchmark/data/crime_prediction/val.jsonl')]
    cov = {10: 0.0, 20: 0.0, 40: 0.0}
    top1 = 0
    for e in va:
        a = e['answer']
        a = a.split('罪名:')[-1].strip() if '罪名:' in a else a
        gold = set(p.strip() for p in a.split(j))
        q = ('请你模拟法官依据下面事实给出罪名。请先进行推理分析，然后将最终答案写在[罪名]和<eoa>之间。\n\n'
             '格式示例：\n- 单个罪名: [罪名]盗窃<eoa>\n- 多个罪名: [罪名]盗窃;诈骗<eoa>\n\n\n## 案件事实\n' + e['question'])
        r = rank(q)
        top1 += bool(gold & set(p.strip() for p in r[0]['target'].split(j)))
        for k in cov:
