        for k, _ in ((3, 0), (5, 0)):
            votes = Counter(x['target'].strip().lower() for x in r[:k])
            hit = votes.most_common(1)[0][0] == g
            if k == 3:
                ok3 += hit
            else:
                ok5 += hit
    n = len(va)
    return {'s2d@1': round(ok1 / n, 3), 's2d@3': round(ok3 / n, 3), 's2d@5': round(ok5 / n, 3)}


def uspto_metrics(rank):
    ex = load('USPTO')
    va = [json.loads(l) for l in open('/workspace/benchmark/data/uspto/val.jsonl')]
